# [LATER-STEP] translation_memory_embedding.py – Embed translated segments for translation-memory search\n# Uses Google Gemini embeddings (concrete provider)\nimport os\nimport requests\nfrom typing import List, Dict\n\n# Provider‑specific signal\nGOOGLE_API_KEY = os.getenv('GOOGLE_API_KEY')\nif not GOOGLE_API_KEY:\n    raise RuntimeError('Set GOOGLE_API_KEY environment variable with Gemini API credentials.')\n\nBASE_URL = 'https://generativelanguage.googleapis.com/v1beta2'\n\nHEADERS = {\n    'Authorization': f'Bearer {GOOGLE_API_KEY}',\n    'Content-Type': 'application/json',\n}\n\ndef embed_translated_segments(segments: List[str]) -> List[Dict[str, Any]]:\n    \"\"\"Generate embeddings for a list of translated text segments.\n\n    Returns a list of dicts with:\n        * 'text': original segment\n        * 'embedding': list of float values (embedding vector)\n    \"\"\"\n    payload = {\n        'inputs': [{'text': seg} for seg in segments],\n        'model': 'models/embed-text-001',  # concrete model identifier\n        'parameters': {\n            'dimensions': 1536,\n        },\n    }\n    resp = requests.post(f\"{BASE_URL}/embeddings:generate\", headers=HEADERS, json=payload)\n    resp.raise_for_status()\n    data = resp.json()\n    # Expected format: { 'embeddings': [{ 'text': ..., 'embedding': [...]} ] }\n    embeddings = []\n    for entry in data.get('embeddings', []):\n        embeddings.append({\n            'text': entry.get('text'),\n            'embedding': entry.get('embedding'),\n        })\n    return embeddings\n\n# Example usage\nif __name__ == '__main__':\n    sample_segments = [\n        'Bonjour le monde!',\n        'How are you?',\n        'El mundo es hermoso.',\n    ]\n    print('Embeddings:', embed_translated_segments(sample_segments))